CREATE TABLE IF NOT EXISTS projects(id text PRIMARY KEY,name text NOT NULL,key_hash text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS streams(project_id text NOT NULL REFERENCES projects(id),source_id text NOT NULL,stream_id text NOT NULL,harness text NOT NULL,next_offset bigint NOT NULL DEFAULT 0,PRIMARY KEY(project_id,source_id,stream_id));
CREATE TABLE IF NOT EXISTS raw_records(id text PRIMARY KEY,project_id text NOT NULL,source_id text NOT NULL,stream_id text NOT NULL,offset_bytes bigint NOT NULL,raw bytea NOT NULL,hash text NOT NULL,metadata jsonb NOT NULL,UNIQUE(project_id,source_id,stream_id,offset_bytes),UNIQUE(project_id,id),FOREIGN KEY(project_id,source_id,stream_id) REFERENCES streams(project_id,source_id,stream_id));
CREATE TABLE IF NOT EXISTS events(id text PRIMARY KEY,project_id text NOT NULL,raw_id text NOT NULL,ordinal int NOT NULL,kind text NOT NULL,pointer text NOT NULL,content_json text NOT NULL,search_text text NOT NULL,metadata jsonb NOT NULL,UNIQUE(project_id,id),UNIQUE(raw_id,ordinal),FOREIGN KEY(project_id,raw_id) REFERENCES raw_records(project_id,id));
CREATE TABLE IF NOT EXISTS extraction_runs(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),status text NOT NULL,input_refs jsonb NOT NULL,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id));
CREATE TABLE IF NOT EXISTS episodes(id text PRIMARY KEY,project_id text NOT NULL,run_id text NOT NULL,goal jsonb NOT NULL,chunk_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,id),FOREIGN KEY(project_id,run_id) REFERENCES extraction_runs(project_id,id));
CREATE TABLE IF NOT EXISTS episode_events(project_id text NOT NULL,episode_id text NOT NULL,event_id text NOT NULL,ordinal int NOT NULL,PRIMARY KEY(episode_id,event_id),UNIQUE(episode_id,ordinal),FOREIGN KEY(project_id,episode_id) REFERENCES episodes(project_id,id),FOREIGN KEY(project_id,event_id) REFERENCES events(project_id,id));
